class _AsyncGoogleAdsNamespace:
    """Google Ads Transparency advertiser lookup, ad search, and creative endpoints."""

    def __init__(self, client: "AsyncScavioClient") -> None:
        self._client = client

    async def advertisers(
        self,
        query: str,
        *,
        region: Optional[str] = None,
        limit: Optional[int] = None,
        **extra: Any,
    ) -> dict[str, Any]:
        """Resolve a brand name or domain to the advertiser_id that search() and creative() are keyed by. Returns two row kinds in one list: 'advertiser' rows carrying the id, verified name, verification country and total ad count as a range, and 'domain' rows carrying a website. A name query returns both kinds; a domain-shaped query returns domains only. Autocomplete-backed, roughly 20 rows per arm, and it does not paginate.

        Costs 1 credit. Returns the API response as a dict.

        Args:
            query: Brand name or domain to resolve (1-200 characters).
            region: ISO 3166-1 alpha-2 country ('US', 'GB', 'DE') or a Google geo criteria id as a string (2-12 characters). Defaults to the UNITED STATES, not worldwide -- the lookup runs against one country's index at a time, so an advertiser who runs no US ads comes back as an empty list. Set it to a country the advertiser actually advertises in.
            limit: Rows per arm (1-20; server default 10). Advertisers and domains are capped separately, so a name query can return up to twice this many rows.
            extra: Additional wire parameters passed through verbatim.
        """
        return await self._client._call("google_ads_advertisers", {"query": query, "region": region, "limit": limit}, extra)

    async def search(
        self,
        *,
        domain: Optional[str] = None,
        advertiser_id: Optional[str] = None,
        region: Optional[str] = None,
        format: Optional[Literal["text", "image", "video"]] = None,
        platform: Optional[Literal["play", "maps", "search", "shopping", "youtube"]] = None,
        topic: Optional[Literal["all", "political"]] = None,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        **extra: Any,
    ) -> dict[str, Any]:
        """Every ad Google Ads Transparency holds for one advertiser: the creative (archived image, rich-media bundle, Google's renderer link, dimensions), advertiser id and name, format, first and last seen dates and days actually run, plus total_ads_min and total_ads_max -- Google publishes the advertiser's ad total as a range, never an exact figure. Up to 100 ads per page (server default 40); paginate by sending next_cursor back as cursor alongside the SAME filters. Provide domain or advertiser_id.

        Costs 1 credit. Returns the API response as a dict.

        Args:
            domain: Advertiser website (1-253 characters): bare host, www host or full URL, reduced to the registrable host. The only way to get `domain` back on each row.
            advertiser_id: Google advertiser id, e.g. 'AR16735076323512287233' (3-40 characters). The shape is checked before any request, so a typo costs no credits. Querying by id drops `domain` from every row.
            region: ISO 3166-1 alpha-2 country ('US', 'GB', 'DE') or a Google geo criteria id as a string (2-12 characters). Scopes the deep links on every row, and the same advertiser can share zero creatives between two countries. Default: worldwide.
            format: Creative format. The three sets are disjoint -- an advertiser's text, image and video ads share no creatives. Default: all formats.
            platform: Google surface the ad ran on. Default: all surfaces.
            topic: Ad topic (server default 'all').
            limit: Ads per page (1-100; server default 40). 100 is a hard upstream ceiling, not our policy: Google answers a larger request with zero rows rather than an error.
            cursor: next_cursor from the previous response (1-4000 characters), 100 ads per page. Re-send the same filters alongside it; next_cursor is null once exhausted.
            extra: Additional wire parameters passed through verbatim.
        """
        return await self._client._call("google_ads_search", {"domain": domain, "advertiser_id": advertiser_id, "region": region, "format": format, "platform": platform, "topic": topic, "limit": limit, "cursor": cursor}, extra)

    async def creative(
        self,
        advertiser_id: str,
        creative_id: str,
        **extra: Any,
    ) -> dict[str, Any]:
        """One creative in full, and the only endpoint carrying its history: every size variation of the asset, the impression bucket, the per-region breakdown with first and last shown dates and a per-surface impression split inside each region, the format, Google's category label and the funder disclosure on political ads. Impressions and first_shown are EEA-only (DSA-compelled) and come back null for US creatives, and an impression bucket may carry only a lower or only an upper bound.

        Costs 1 credit. Returns the API response as a dict.

        Args:
            advertiser_id: Google advertiser id, e.g. 'AR16735076323512287233' (3-40 characters).
            creative_id: Creative id (3-40 characters). It must belong to the advertiser_id sent with it -- the lookup is keyed by the pair and a mismatched pair is a 404.
            extra: Additional wire parameters passed through verbatim.
        """
        return await self._client._call("google_ads_creative", {"advertiser_id": advertiser_id, "creative_id": creative_id}, extra)

