class _AsyncJcpenneyNamespace:
    """JCPenney search, product (batch of 20), category, brand, clearance / sale / Black Friday / BOGO deal listings, store locator, store unit counts, suggestions, coupon code, review text and Q&A endpoints."""

    def __init__(self, client: "AsyncScavioClient") -> None:
        self._client = client

    async def search(
        self,
        query: str,
        *,
        brand: Optional[Union[str, list[str]]] = None,
        deal: Optional[Union[str, list[str]]] = None,
        exact: Optional[bool] = None,
        page: Optional[int] = None,
        sort: Optional[Literal["relevance", "new_arrivals", "best_sellers", "rating", "price_low_to_high", "price_high_to_low"]] = None,
        color: Optional[Union[str, list[str]]] = None,
        size: Optional[Union[str, list[str]]] = None,
        price_range: Optional[Union[str, list[str]]] = None,
        filters: Optional[dict[str, Any]] = None,
        **extra: Any,
    ) -> dict[str, Any]:
        """Search jcpenney.com (US) by keyword, filtered by brand, color, size, price range, deal label (SALE, CLEARANCE...) and any facet value (gender, store availability, rating, rise...), sorted by relevance, new arrivals, best sellers, rating or price. 48 products per page (at most 25 pages = 1,200 items), each with id, title, brand, URL, image, sku_id, price and price_max (current), regular_price and regular_price_max, price_type (sale, clearance, original), percent_off, deal_label (BIG BUY!, CLEARANCE...), coupon_price with coupon_code (the price after today's coupon), rating, review_count, badge (Only at JCP, NEW, Few Left), availability_label (Same Day Pickup, Online Only...), colors with their SKU ids, and is_marketplace with the seller for third-party items. Also returns total, page, total_pages, the sort applied, applied_filters and every facet (id, label and values with their value, count and a selected flag; any of them works in filters). Prices are product-level ranges: JCPenney does not expose a price per size or color. Average rating and review count here; review text is reviews(). Prices in USD. When the site autocorrects the keyword, corrected_query says so; when it sends a keyword to a deal or category listing (doorbusters), redirected_to says where and the items are that listing's.

        Costs 1 credit. Returns the API response as a dict.

        Args:
            query: Search keywords, e.g. 'jeans'.
            brand: Only this brand (or any of several), as the Brand facet lists it ("levi's", "nike", "st. john's bay").
            deal: Only items with this Deals & Promotions label ('SALE', 'CLEARANCE', 'BIG BUY!'...), as the facet lists it.
            exact: JCPenney narrows many keywords to a category on its own (jeans -> the Jeans category, visible in applied_filters). True searches the keyword across every category instead.
            page: Results page, 1-based (48 items per page, at most 25 pages). A page past the last one returns an empty items list with the real total. Defaults to 1.
            sort: relevance (default), new_arrivals, best_sellers, rating (highest rated first), price_low_to_high or price_high_to_low. The price orders are JCPenney's own and loose: sort the items by price yourself when you need a strict order.
            color: Only this color (or any of several), as the Color facet lists it (black, blue, beige...).
            size: Only this size (or any of several), as the Size facet lists it (m, 12, 32x30...).
            price_range: A Price Range facet value ('under $5', '$20 - $24'...).
            filters: Any facet from a previous response: {facets[].id: facets[].values[].value, or a list of values (any of them)}, e.g. {'gender': 'women'}, {'store_availability': 'same day pickup'}, {'average_rating': '4 rating'}. Several facets combine (AND).
            extra: Additional wire parameters passed through verbatim.
        """
        return await self._client._call("jcpenney_search", {"query": query, "brand": brand, "deal": deal, "exact": exact, "page": page, "sort": sort, "color": color, "size": size, "price_range": price_range, "filters": filters}, extra)

